/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Every status that is not closed. `status=open` expands to this list. */
export const OPEN_ISSUE_STATUSES: readonly IssueStatus[] = ISSUE_STATUSES.filter(
  (status) => !CLOSED_ISSUE_STATUSES.includes(status),
);

export const ISSUE_STATUS_GROUPS = ["open", "closed"] as const;

export type IssueStatusGroup = (typeof ISSUE_STATUS_GROUPS)[number];

/** A status filter token: one status, or a group the list expands. */
export type IssueStatusFilter = IssueStatus | IssueStatusGroup;

/** `assignee=me` / `author=me`. The service resolves it to the acting user. */
export const ME_TOKEN = "me" as const;

export type MeToken = typeof ME_TOKEN;

/**
 * Expands status tokens. `open` and `closed` become their members; a concrete
 * status stays itself; anything else is dropped. Order follows the input, with
 * group members in `ISSUE_STATUSES` order, and duplicates collapse.
 */
export function expandStatusFilters(
  tokens: readonly string[],
): readonly IssueStatus[] {
  const seen = new Set<IssueStatus>();
  const expanded: IssueStatus[] = [];

  for (const token of tokens) {
    const members = statusTokenMembers(token);
    if (members === null) continue;
    for (const status of members) {
      if (seen.has(status)) continue;
      seen.add(status);
      expanded.push(status);
    }
  }

  return expanded;
}

function statusTokenMembers(token: string): readonly IssueStatus[] | null {
  if (token === "open") return OPEN_ISSUE_STATUSES;
  if (token === "closed") return CLOSED_ISSUE_STATUSES;
  return (ISSUE_STATUSES as readonly string[]).includes(token)
    ? [token as IssueStatus]
    : null;
}

