/** Next.js `searchParams` or anything with `URLSearchParams#get`. */
export function readableSearchParams(
  search: ReadableParams | Readonly<Record<string, string | string[] | undefined>>,
): ReadableParams {
  if (typeof (search as ReadableParams).get === "function") {
    return search as ReadableParams;
  }

  const record = search as Readonly<Record<string, string | string[] | undefined>>;
  return {
    get(name: string): string | null {
      const value = record[name];
      if (typeof value === "string") return value;
      if (Array.isArray(value)) return value.join(",");
      return null;
    },
  };
}

function personToken(raw: string): UserId | MeToken {
  return raw === ME_TOKEN ? ME_TOKEN : (raw as UserId);
}

export function parseIssueFilterParams(params: ReadableParams): IssueFilter {
  const statuses = expandStatusFilters(splitList(params.get("status")));
  const priorities = splitList(params.get("priority")).filter(
    (value): value is IssuePriority =>
      ISSUE_PRIORITIES.includes(value as IssuePriority),
  );
  const labelIds = splitList(params.get("label")) as readonly LabelId[];
  const project = params.get("project");
  const assignee = params.get("assignee");
  const author = params.get("author");
  const query = params.get("q");
  const dueBefore = params.get("due_before")?.trim() ?? null;
  const archived = params.get("archived");

  const filter: IssueFilter = {
    ...(project !== null ? { projectId: project as ProjectId } : {}),
    ...(statuses.length > 0 ? { status: statuses } : {}),
    ...(priorities.length > 0 ? { priority: priorities } : {}),
    ...(assignee !== null
      ? {
