input.new_string:
import { z } from "zod";
import { isDueBeforeValue } from "@/lib/date";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import {
  archiveScopeSchema,
  isoTimestampSchema,
  issueIdSchema,
  labelIdSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const issuePrioritySchema = z.enum([
  "none",
  "low",
  "medium",
  "high",
  "urgent",
]);

/** Statuses plus the `open` and `closed` groups the list filter accepts. */
export const issueStatusFilterSchema = z.enum([
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
  "open",
  "closed",
]);

/** A comma-separated string or an array. Unknown tokens fail the whole value. */
function asCommaList(value: unknown): unknown {
  if (value === undefined || value === null || value === "") return undefined;
  if (typeof value === "string") {
    const parts = value
      .split(",")
      .map((part) => part.trim())
      .filter((part) => part.length > 0);
    return parts.length > 0 ? parts : undefined;
  }
  return value;
}

export const issueStatusListSchema = z.preprocess(
  asCommaList,
  z.array(issueStatusFilterSchema).optional(),
);

export const issuePriorityListSchema = z.preprocess(
  asCommaList,
  z.array(issuePrioritySchema).optional(),
);

export const labelIdListSchema = z.preprocess(
  asCommaList,
  z.array(labelIdSchema).optional(),
);

const userOrMeSchema = z.union([z.literal("me"), userIdSchema]);

/** `none` is the URL spelling of unassigned; `me` is resolved by the service. */
export const assigneeFilterSchema = z.preprocess(
  (value) => (value === "none" ? null : value),
  userOrMeSchema.nullable().optional(),
);

export const authorFilterSchema = userOrMeSchema.optional();

export const dueBeforeSchema = z
  .string()
  .refine(
    isDueBeforeValue,
    "expected a YYYY-MM-DD date or an ISO-8601 timestamp",
  );

export const issueFilterSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema.optional(),
    status: issueStatusListSchema,
    priority: issuePriorityListSchema,
    assigneeId: assigneeFilterSchema,
    authorId: authorFilterSchema,
    labelIds: labelIdListSchema,
    query: z.string().max(200).optional(),
    dueBefore: dueBeforeSchema.optional(),
    /** URL vocabulary: `1` mixes archived in, `only` lists archived alone. */
    archived: z.enum(["1", "only"]).optional(),
    archivedOnly: z.boolean().optional(),
  })
  .extend(pageRequestSchema.shape)
  .extend(archiveScopeSchema.shape)
  .transform((value) => {
    const archivedOnly = value.archived === "only" || value.archivedOnly === true;
    const includeArchived = archivedOnly
      ? value.includeArchived
      : value.archived === "1"
        ? true
        : value.includeArchived;
    const { archived: _archived, ...rest } = value;
    return {
      ...rest,
      ...(includeArchived === undefined ? {} : { includeArchived }),
      ...(archivedOnly ? { archivedOnly: true as const } : {}),
    };
  });

