input.new_string:
import { z } from "zod";
import { orgIdSchema, projectIdSchema } from "./common";
import { issuePriorityListSchema, issueStatusListSchema } from "./issue";

import { dueBeforeExclusiveBound } from "@/lib/date";
import { expandStatusFilters, ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";

input.old_string:
/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const scope: ArchiveScope = shouldFilterArchived(input)
    ? {}
    : { includeArchived: true };

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    livePredicate(issues.archivedAt, scope),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    input.status === undefined || input.status.length === 0
      ? undefined
      : inArray(issues.status, [...input.status]),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    // `null` and `undefined` both arrive from the "Anyone" option of the
    // filter bar, so neither narrows the list.
    input.assigneeId ? eq(issues.assigneeId, input.assigneeId) : undefined,
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    input.dueBefore === undefined ? undefined : lt(issues.dueAt, input.dueBefore),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    input.labelIds === undefined || input.labelIds.length === 0
      ? undefined
      : inArray(
          issues.id,
          getDb()
            .select({ id: issueLabels.issueId })
            .from(issueLabels)
            .where(
              and(
                orgPredicate(issueLabels.orgId, input.orgId),
                inArray(issueLabels.labelId, [...input.labelIds]),
              ),
            ),
        ),
  );
}

input.new_string:
/** Live rows, live plus archived, or archived alone. `only` wins over include. */
function archivedPredicate(input: IssueFilterInput): SQL | undefined {
  const liveOnly = shouldFilterArchived(input);
  if (input.archivedOnly === true) return isNotNull(issues.archivedAt);
  const scope: ArchiveScope = liveOnly ? {} : { includeArchived: true };
  return livePredicate(issues.archivedAt, scope);
}

/**
 * An issue matches only when it carries every listed label. One `IN` per label
 * is all-of; a single `IN (...)` would be any-of and would also inflate counts.
 */
function everyLabelPredicate(
  orgId: IssueFilterInput["orgId"],
  labelIds: readonly string[],
): SQL | undefined {
  const unique = [...new Set(labelIds)];
  if (unique.length === 0) return undefined;
  return and(
    ...unique.map((labelId) =>
      inArray(
        issues.id,
        getDb()
          .select({ id: issueLabels.issueId })
          .from(issueLabels)
          .where(
            and(
              orgPredicate(issueLabels.orgId, orgId),
              eq(issueLabels.labelId, labelId),
            ),
          ),
      ),
    ),
  );
}

/** Strict upper bound. A calendar date includes that whole UTC day. */
function dueBeforePredicate(dueBefore: string | undefined): SQL | undefined {
  if (dueBefore === undefined) return undefined;
  const bound = dueBeforeExclusiveBound(dueBefore);
  if (bound === null) return undefined;
  return and(isNotNull(issues.dueAt), lt(issues.dueAt, bound));
}

/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const statuses = expandStatusFilters(input.status ?? []);

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    archivedPredicate(input),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    statuses.length === 0 ? undefined : inArray(issues.status, [...statuses]),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    // `undefined` is "anyone". `null` is unassigned and must narrow the list.
    input.assigneeId === undefined
      ? undefined
      : input.assigneeId === null
        ? isNull(issues.assigneeId)
        : eq(issues.assigneeId, input.assigneeId),
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    dueBeforePredicate(input.dueBefore),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    everyLabelPredicate(input.orgId, input.labelIds ?? []),
  );
}

