/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = filter.status ?? [];
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  return withStatus(filter, next);
}

/** Toggles a whole group (`open` / `closed`) in one click. */
export function toggleStatusGroup(
  filter: IssueFilter,
  members: readonly IssueStatus[],
): IssueFilter {
  const current = filter.status ?? [];
  const allOn = members.every((status) => current.includes(status));
  const next = allOn
    ? current.filter((status) => !members.includes(status))
    : [
        ...current,
        ...members.filter((status) => !current.includes(status)),
      ];
  return withStatus(filter, next);
}

function withStatus(
  filter: IssueFilter,
  status: readonly IssueStatus[],
): IssueFilter {
  const { status: _dropped, ...rest } = filter;
  return status.length === 0 ? rest : { ...rest, status };
}

function groupActive(
  filter: IssueFilter,
  members: readonly IssueStatus[],
): boolean {
  const current = filter.status ?? [];
  return members.every((status) => current.includes(status));
}

