}

/** Toggles a whole group (`open` / `closed`) in one click. */
export function toggleStatusGroup(
  filter: IssueFilter,
  members: readonly IssueStatus[],
): IssueFilter {
  const current = filter.status ?? [];
  const allOn = members.every((status) => current.includes(status));
  const next = allOn
    ? current.filter((status) => !members.includes(status))
    : [
        ...current,
        ...members.filter((status) => !current.includes(status)),
      ];
  return withStatus(filter, next);
}

