import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { parseIssueFilterParams, issueFilterToParams } from "@/hooks/issue-filter-params";
import { issueFilterSchema } from "@/schemas/issue";
import { exportIssuesSchema } from "@/schemas/export";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { listIssues } from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import { OPEN_ISSUE_STATUSES } from "@/types/issue";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("filter-check");
});

afterAll(() => {
  cleanup();
});

async function add(overrides: Record<string, unknown>) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    {
      ...issueInput(tenant.org.id, tenant.project.id, {}),
      ...overrides,
    } as never,
    tenant.userIds.owner,
    number,
  );
}

describe("filter vocabulary", () => {
  it("agrees across codec, schema, and repository", async () => {
    const bug = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "bug",
      color: "#ef4444",
      description: null,
    });
    const regression = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "regression",
      color: "#f59e0b",
      description: null,
    });

    const both = await add({
      title: "both labels",
      status: "todo",
      assigneeId: null,
      dueAt: "2026-03-15T18:00:00.000Z",
      labelIds: [bug.id, regression.id],
    });
    const onlyBug = await add({
      title: "only bug",
      status: "todo",
      assigneeId: tenant.userIds.member,
      dueAt: "2026-03-15T08:00:00.000Z",
      labelIds: [bug.id],
    });
    const mine = await add({
      title: "mine open",
      status: "in_progress",
      assigneeId: tenant.userIds.owner,
      dueAt: "2026-03-16T00:00:00.000Z",
      labelIds: [],
    });
    const done = await add({
      title: "done",
      status: "done",
      assigneeId: tenant.userIds.owner,
      dueAt: "2026-03-15T00:00:00.000Z",
      labelIds: [bug.id, regression.id],
    });
    const archived = await add({
      title: "archived",
      status: "todo",
      assigneeId: null,
      dueAt: null,
      labelIds: [],
    });
    await issueRepo.archiveIssue(tenant.org.id, archived.id);

    const labelPage = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 50,
      cursor: null,
      labelIds: [bug.id, regression.id],
    });
    expect(labelPage.items.map((row) => row.id).sort()).toEqual(
      [both.id, done.id].sort(),
    );
    expect(labelPage.total).toBe(labelPage.items.length);
    expect(labelPage.items.map((row) => row.id)).not.toContain(onlyBug.id);

    const unassigned = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 50,
      cursor: null,
      assigneeId: null,
    });
    expect(unassigned.items.every((row) => row.assigneeId === null)).toBe(true);
    expect(unassigned.items.map((row) => row.id)).toContain(both.id);
